"""Environment settings loader and merger."""
from typing import Dict, Any
import copy

DEFAULT_CONN_TIMEOUT = 30

def load_system_env() -> Dict[str, Any]:
    return {"timeout": DEFAULT_CONN_TIMEOUT}

def _merge_recursive(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    """
    Recursively merge override into base.
    - Dicts are merged recursively.
    - Lists are concatenated (base + override) with duplicates removed (first-seen order).
    - Other values are replaced.
    Returns a new dict structure to ensure immutability/isolation (H03, H12).
    """
    result = copy.deepcopy(base)
    for key, value in override.items():
        if key in result:
            base_val = result[key]
            if isinstance(base_val, dict) and isinstance(value, dict):
                result[key] = _merge_recursive(base_val, value)
            elif isinstance(base_val, list) and isinstance(value, list):
                # H12: Concatenate base then override, remove duplicates preserving order
                combined = base_val + value
                seen = []
                deduped = []
                for item in combined:
                    if item not in seen:
                        seen.append(item)
                        deduped.append(item)
                result[key] = deduped
            else:
                # Replace scalar or non-matching types, deep copy if complex to be safe
                result[key] = copy.deepcopy(value) if isinstance(value, (dict, list)) else value
        else:
            result[key] = copy.deepcopy(value) if isinstance(value, (dict, list)) else value
    return result

def merge_env_settings(base_settings: Dict[str, Any], override_settings: Dict[str, Any]) -> Dict[str, Any]:
    return _merge_recursive(base_settings, override_settings)
